{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "In cirrhotic patients, pentoxifylline absolute bioavailability was 0.71 ± 0.24 after a 400 mg sustained-release tablet, directly matching the cirrhosis condition and supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Theophylline absolute bioavailability was 93.4 ± 6.3% in children after oral administration compared with intravenous theophylline, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Temozolomide showed 100% absolute oral bioavailability in pharmacokinetic studies with capsules, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved evidence molecules show absolute oral bioavailability well above the 20% threshold, including a direct cirrhosis-matched absolute bioavailability measurement of 71% for pentoxifylline. The prediction is therefore high.",
  "evidence_gaps": [
    "Only one retrieved record directly reports bioavailability in cirrhotic patients; most other evidence comes from healthy subjects or general patient populations.",
    "Pentoxifylline has conflicting non-cirrhotic records showing lower bioavailability, but the cirrhosis-matched absolute record is high and was used for the molecule-level direction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

